window.OSHA_QUESTIONS_SET3 = [
  { id: "fk-01", category: "forklift", topic: "Standard", q: "Powered industrial trucks (forklifts) in general industry are covered by:", choices: ["29 CFR 1910.178", "1926.500 only", "1910.147 only", "The MUTCD only"], a: 0, why: "1910.178 is the PIT standard. Construction also uses 1926.602 for material-handling equipment." },
  { id: "fk-02", category: "forklift", topic: "Certification", q: "Forklift operator certification is issued by:", choices: ["OSHA on a plastic DOL card", "The employer after training and evaluation", "The state DMV in every state", "The truck manufacturer only"], a: 1, why: "There is no federal “OSHA forklift license.” Employers certify operators on the equipment they will use." },
  { id: "fk-03", category: "forklift", topic: "Training parts", q: "PIT training must include:", choices: ["Formal instruction, practical training, and an evaluation of performance in the workplace", "A video only", "Reading the data plate only", "A written test with no driving"], a: 0, why: "1910.178(l)(2): all three. Topics include stability, load charts, and workplace-specific hazards." },
  { id: "fk-04", category: "forklift", topic: "Evaluation interval", q: "Operator performance must be evaluated at least every:", choices: ["6 months", "3 years", "10 years", "Never after initial cert"], a: 1, why: "1910.178(l)(4)(iii): at least once every 3 years, and sooner after an incident or unsafe operation." },
  { id: "fk-05", category: "forklift", topic: "Refresher", q: "Refresher training is required when:", choices: ["The operator is involved in an accident, near miss, or is observed operating unsafely, or conditions change", "The operator asks for a new hat", "Only if they change companies in another state", "Never"], a: 0, why: "Also required if they are assigned a different type of truck." },
  { id: "fk-06", category: "forklift", topic: "Data plate", q: "The forklift data plate shows:", choices: ["Radio stations", "Capacity, load center, and truck type/weight information", "The operator’s name", "Only the paint color"], a: 1, why: "Never exceed capacity. Attachments change capacity — the plate must reflect them." },
  { id: "fk-07", category: "forklift", topic: "Stability triangle", q: "A sit-down counterbalanced forklift is stable when the combined center of gravity stays:", choices: ["Outside the rear axle", "Inside the stability triangle formed by the front wheels and the pivot of the steer axle", "Above the overhead guard", "On the fork tips"], a: 1, why: "Raising a load, tilting forward, turning, and off-center loads move the CG. That is how tip-overs happen." },
  { id: "fk-08", category: "forklift", topic: "Tip-over", q: "If a sit-down rider forklift tips over, the operator should:", choices: ["Jump downhill", "Stay seated, hold on, and lean away from the fall, with the seat belt on", "Stand on the battery", "Grab the overhead guard and leap"], a: 1, why: "Jumping is how operators are crushed by the overhead guard. Belt on." },
  { id: "fk-09", category: "forklift", topic: "Travel", q: "When traveling with a load on a ramp:", choices: ["Load uphill (upgrade) when loaded, generally", "Load downhill always", "Turn sideways on the ramp", "Raise the load to see"], a: 0, why: "Loaded: forks uphill. Unloaded: forks downhill. Keep the load upgrade so it cannot slide off." },
  { id: "fk-10", category: "forklift", topic: "Unloaded ramp", q: "When traveling without a load on a grade, the forks generally point:", choices: ["Uphill", "Downhill", "Sideways", "As high as possible"], a: 1, why: "Unloaded trucks are heavier at the rear. Forks downhill keeps the CG more stable on grades." },
  { id: "fk-11", category: "forklift", topic: "Speed", q: "Forklift speed should be:", choices: ["The same as highway traffic", "Slow enough to stop safely for conditions, loads, and pedestrians", "As fast as the truck will go in an aisle", "Cruise-control at 20 mph indoors"], a: 1, why: "1910.178(n)(8): speeds that allow stopping. Wet floors and blind corners need slower speeds." },
  { id: "fk-12", category: "forklift", topic: "Horn", q: "Sound the horn:", choices: ["At blind corners, when approaching pedestrians, and when required by workplace rules", "Continuously", "Never, it scares people", "Only outdoors"], a: 0, why: "1910.178(n)(4): slow down and sound the horn at cross-aisles and other locations where vision is obstructed." },
  { id: "fk-13", category: "forklift", topic: "Parking", q: "When leaving a forklift unattended, you must:", choices: ["Leave it running in gear", "Fully lower forks, neutralize controls, shut off power, and set the brake; chock if on an incline", "Leave forks at eye level as a warning", "Park in a pedestrian lane"], a: 1, why: "1910.178(m)(5): unattended means operator more than 25 feet away or out of sight. If still in view within 25 feet, at least lower forks, neutralize, and set brake." },
  { id: "fk-14", category: "forklift", topic: "Unattended definition", q: "A PIT is considered unattended when the operator is:", choices: ["Sitting on it talking", "More than 25 feet away or whenever the truck is not in view", "Wearing a seat belt", "On a break in the cab"], a: 1, why: "1910.178(m)(5)(ii)–(iii)." },
  { id: "fk-15", category: "forklift", topic: "People on forks", q: "Lifting people on forks or pallets is:", choices: ["Allowed if they hold on", "Prohibited unless a properly designed work platform is used and manufacturer/OSHA conditions are met", "Required for order picking always", "Fine below 4 feet"], a: 1, why: "1910.178(m)(3): no riders except as allowed. Construction aerial lifts have their own rules (1926.453)." },
  { id: "fk-16", category: "forklift", topic: "Attachments", q: "Side shifters, clamps, and jibs:", choices: ["Never change capacity", "Can reduce capacity and must be approved; the data plate should match the configuration", "Let you exceed the plate by 20%", "Are decorative"], a: 1, why: "The load moment changes. Get the dealer/manufacturer rating." },
  { id: "fk-17", category: "forklift", topic: "Battery charging", q: "Battery charging areas need:", choices: ["No special precautions", "Ventilation, no smoking, eyewash/emergency equipment as required, and PPE for acid", "Open flames to dry batteries", "Charging on a wooden stair"], a: 1, why: "1910.178(g): hydrogen gas is explosive. Keep ignition sources away. Neutralize acid spills properly." },
  { id: "fk-18", category: "forklift", topic: "Propane change", q: "When changing an LP tank:", choices: ["Smoke to check for leaks", "Shut the valve, wear PPE as required, and check connections; do it in a well-ventilated area away from ignition", "Change tanks indoors next to a heater", "Vent fuel into a drain"], a: 1, why: "LP is heavier than air. Leaks pool low. No smoking." },
  { id: "fk-19", category: "forklift", topic: "Daily inspect", q: "Pre-use inspection typically includes:", choices: ["Tires, forks, mast, chains, leaks, overhead guard, horn, lights, and brakes", "Only the cup holder", "Paint chips", "Radio volume"], a: 0, why: "1910.178(q)(7): examine at least daily. Remove from service if unsafe." },
  { id: "fk-20", category: "forklift", topic: "Remove from service", q: "If the brakes fail the inspection, the operator should:", choices: ["Drive slowly to the shop across the yard", "Not operate the truck until it is repaired", "Use the parking brake as service brakes", "Have a spotter push it"], a: 1, why: "1910.178(p)(1): any powered industrial truck not in safe operating condition shall be removed from service." },
  { id: "fk-21", category: "forklift", topic: "Load backrest", q: "A load backrest extension is used to:", choices: ["Increase engine power", "Prevent the load from falling toward the operator when stacked high on the forks", "Replace the overhead guard", "Tow trailers"], a: 1, why: "1910.178(e)(2): backrest of adequate height when the type of load requires it." },
  { id: "fk-22", category: "forklift", topic: "Overhead guard", q: "The overhead guard protects against:", choices: ["Falling objects (small packages/objects); it is not a guarantee against a full rack collapse", "Electrocution", "CO", "Noise"], a: 0, why: "1910.178(e)(1): overhead guard. It will not stop a 2,000-lb load dropped from a high rack." },
  { id: "fk-23", category: "forklift", topic: "Dock", q: "Before driving into a trailer, the operator should:", choices: ["Assume the trailer cannot move", "Verify the trailer is chocked/jack-stand as required, dock plate is secure, and the floor will hold the truck", "Enter at full speed", "Raise the load to the roof"], a: 1, why: "Trailer creep and landing-gear collapse kill operators. Wheel chocks, restraints, and inspection of the trailer floor matter." },
  { id: "fk-24", category: "forklift", topic: "Narrow aisle", q: "Stand-up reach trucks have different:", choices: ["Stability characteristics and training needs than sit-down counterbalanced trucks", "OSHA standards that ban them", "Rules that skip evaluation", "Need for data plates"], a: 0, why: "1910.178(l): training must be truck-type specific. Reach, order-picker, and pallet jack are different." },
  { id: "fk-25", category: "forklift", topic: "Pedestrian right", q: "Pedestrians in a warehouse should:", choices: ["Share unmarked aisles at running speed", "Use designated walkways, make eye contact, and never walk under a raised load", "Assume the operator sees them", "Ride the forks to the break room"], a: 1, why: "Separate people and PITs when you can. High-vis helps but does not replace distance." },
  { id: "fk-26", category: "forklift", topic: "Carbon monoxide", q: "IC (internal combustion) forklifts in poorly ventilated areas can cause:", choices: ["CO poisoning", "Only extra heat that is healthy", "Better air quality", "No hazard if propane is used"], a: 0, why: "Propane, gasoline, and diesel all produce CO. Maintain tune-ups and ventilate. Consider electric trucks indoors." },
  { id: "fk-27", category: "forklift", topic: "Nameplate missing", q: "If the capacity plate is missing or unreadable:", choices: ["Guess 5,000 lb", "Do not operate until it is replaced with the correct information", "Use the last truck’s plate", "Ask a coworker to estimate"], a: 1, why: "1910.178(a)(6): nameplates and markings must be in place and maintained." },
  { id: "fk-28", category: "forklift", topic: "Age", q: "OSHA’s PIT standard requires operators to be:", choices: ["At least 18 years old", "16 with a parent note", "21 for all warehouses", "Any age if supervised"], a: 0, why: "Hazardous-occupations orders and 1910.178 practice: 18 is the general minimum for forklifts." },
  { id: "fk-29", category: "forklift", topic: "Seat belt enforcement", q: "Employers must:", choices: ["Require use of operator restraint systems provided on the truck", "Remove seat belts so operators can jump", "Ignore belts if production is behind", "Only install belts on new trucks and never use them"], a: 0, why: "OSHA enforces seat-belt use under 1910.178(l) training and the General Duty Clause / manufacturer instructions." },
  { id: "fk-30", category: "forklift", topic: "Modifications", q: "Modifications that affect capacity or safe operation:", choices: ["Are fine if welded by a buddy", "Must have prior written approval from the manufacturer", "Never need documentation", "Are required by OSHA annually"], a: 1, why: "1910.178(a)(4): manufacturer approval. Then update the plate." },

  { id: "hz-01", category: "hazwoper", topic: "Standard", q: "HAZWOPER is:", choices: ["29 CFR 1910.120 (and 1926.65 for construction)", "The fall protection standard", "A type of hard hat", "Only an EPA rule with no OSHA overlap"], a: 0, why: "Hazardous Waste Operations and Emergency Response covers cleanup, TSD facilities, and emergency response to releases." },
  { id: "hz-02", category: "hazwoper", topic: "40-hour", q: "General site workers on a hazardous-waste cleanup site who are exposed to hazards generally need:", choices: ["4 hours of awareness", "40 hours of off-site instruction plus a minimum of 3 days actual field experience under a supervisor", "OSHA 10 only", "A forklift card only"], a: 1, why: "1910.120(e)(3)(i): 40 hours + 3 days supervised field experience for general site workers." },
  { id: "hz-03", category: "hazwoper", topic: "24-hour", q: "Workers on site only occasionally for a specific limited task, with unlikely exposure above PELs, may qualify for:", choices: ["No training", "24 hours of training plus one day of field experience (with limits in the standard)", "80 hours", "A PhD in chemistry"], a: 1, why: "1910.120(e)(3)(ii)–(iii): 24-hour category is narrower than 40-hour general site workers." },
  { id: "hz-04", category: "hazwoper", topic: "8-hour refresher", q: "HAZWOPER annual refresher is generally:", choices: ["8 hours", "40 hours every year", "Optional", "15 minutes"], a: 0, why: "1910.120(e)(8): 8 hours of refresher training annually for those who need it." },
  { id: "hz-05", category: "hazwoper", topic: "First responder awareness", q: "First responder awareness level personnel:", choices: ["Stop, look, and call — they do not try to contain the release beyond initiating the emergency response system", "Don Level A and enter the hot zone", "Patch tank cars", "Act as the incident commander always"], a: 0, why: "1910.120(q)(6)(i): awareness = recognize, notify, and stay back." },
  { id: "hz-06", category: "hazwoper", topic: "Operations level", q: "First responder operations level personnel:", choices: ["Respond for defensive purposes — contain from a safe distance, keep it from spreading, without trying to stop the release at the source", "Perform offensive source control in all cases", "Need no training", "Only write reports"], a: 0, why: "1910.120(q)(6)(ii): at least 8 hours or equivalent competency. Defensive, not offensive." },
  { id: "hz-07", category: "hazwoper", topic: "Technician", q: "Hazardous materials technicians:", choices: ["Approach the point of release to plug, patch, or stop it (offensive)", "Only call 911", "Are the same as awareness", "Never use PPE"], a: 0, why: "1910.120(q)(6)(iii): 24 hours plus competency. They work in the hot zone with a buddy system." },
  { id: "hz-08", category: "hazwoper", topic: "IC", q: "The Incident Commander at a HAZMAT emergency must have:", choices: ["At least 24 hours of training equal to the operations level plus additional competency in the ICS and hazards", "Only a radio", "Awareness only", "No training if they are a manager"], a: 0, why: "1910.120(q)(6)(v): IC training is specified. ICS structure is required." },
  { id: "hz-09", category: "hazwoper", topic: "Buddy system", q: "In the hot zone during emergency response, operations typically use:", choices: ["Lone workers to reduce exposure", "The buddy system", "No communication", "Cell phones only without radios"], a: 1, why: "1910.120(q)(3): buddy system and backup personnel. Nobody enters alone." },
  { id: "hz-10", category: "hazwoper", topic: "ERP", q: "An Emergency Response Plan for chemical emergencies must include:", choices: ["Pre-emergency planning, personnel roles, communication, PPE, and evacuation among other elements", "Only a phone number on the wall", "A map of the cafeteria", "Nothing written"], a: 0, why: "1910.120(q)(2) lists required elements. If you will not respond, you must have an emergency action plan and evacuate." },
  { id: "hz-11", category: "hazwoper", topic: "Evacuate option", q: "Employers who will evacuate all employees and not respond to a release:", choices: ["Still need an emergency action plan (1910.38) and to call in outside responders", "Need a full technician team on every shift", "Need no plan", "Only need SDS"], a: 0, why: "1910.120(q)(1): you can choose not to respond, but you must evacuate and have an EAP." },
  { id: "hz-12", category: "hazwoper", topic: "Site control", q: "Typical HAZWOPER work zones are:", choices: ["Hot (exclusion), warm (contamination reduction), and cold (support)", "Only a parking lot", "Red and blue only for electrical", "Inside and outside the county"], a: 0, why: "1910.120(d) and (q): control zones limit spread of contamination." },
  { id: "hz-13", category: "hazwoper", topic: "Decon", q: "Decontamination is:", choices: ["Optional if you are careful", "Required to prevent spreading contaminants; the line is set up before anyone enters in a contaminated state", "A shower at home the next day only", "Only for tools, never people"], a: 1, why: "1910.120(k): written decon procedures. Gross decon in the CRZ." },
  { id: "hz-14", category: "hazwoper", topic: "Medical", q: "HAZWOPER medical surveillance is generally required for:", choices: ["Employees in certain cleanup jobs, wearing respirators 30+ days/year, or injured from exposure, among other triggers", "Office staff only", "Nobody", "Only contractors from other states"], a: 0, why: "1910.120(f): medical exams before assignment, yearly (or biennial with physician approval), and at termination in many cases." },
  { id: "hz-15", category: "hazwoper", topic: "Monitoring", q: "Air monitoring on a hazardous-waste site is used to:", choices: ["Determine PPE, work zones, and whether IDLH or flammable conditions exist", "Entertain the crew", "Replace the site safety plan", "Measure only noise"], a: 0, why: "1910.120(h): initial and periodic monitoring. Know your meter’s limitations (correction factors, O2 for LEL)." },
  { id: "hz-16", category: "hazwoper", topic: "IDLH HAZWOPER", q: "If a hazardous-waste site atmosphere is IDLH, you generally need:", choices: ["N95s", "Positive-pressure SCBA or equivalent, and a standby rescue person", "Surgical masks", "No respiratory protection if you hold your breath"], a: 1, why: "1910.120(g)(3)(iii) and 1910.134 IDLH rules." },
  { id: "hz-17", category: "hazwoper", topic: "Site safety plan", q: "A written safety and health program for cleanup operations includes:", choices: ["An organizational structure, work plan, and site-specific safety and health plan", "Only invoices", "A packing list", "Verbal instructions once"], a: 0, why: "1910.120(b): comprehensive program. The SSHP addresses hazards of that site." },
  { id: "hz-18", category: "hazwoper", topic: "Drums", q: "Opening or moving unlabeled drums on a waste site:", choices: ["Is casual labor", "Requires procedures for handling shock-sensitive, explosive, or unknown drums; staged and inspected carefully", "Should be done by rolling them down a hill", "Needs no PPE"], a: 1, why: "1910.120(j): drum and container handling. Remote opening, grounding, and staging matter." },
  { id: "hz-19", category: "hazwoper", topic: "TSD", q: "Workers at RCRA TSD facilities generally need:", choices: ["24 hours of training plus competency, with 8-hour refresher (or equivalent program)", "No training if they have OSHA 10", "40 hours if they never go outside", "Only a forklift card"], a: 0, why: "1910.120(p)(7): TSD training is 24 hours initially in many cases, not always the 40-hour cleanup course." },
  { id: "hz-20", category: "hazwoper", topic: "PPE levels", q: "EPA/OSHA chemical protective ensemble Level A is:", choices: ["Street clothes", "Vapor-tight suit with SCBA (highest skin and respiratory protection)", "Apron and gloves only", "Hard hat and vest only"], a: 1, why: "Level B is SCBA with non-vapor-tight suit. Level C is APR with similar clothing. Level D is basic work uniform. Select by the hazard, not the alphabet." },
  { id: "hz-21", category: "hazwoper", topic: "Level D", q: "Level D protection is:", choices: ["Adequate for IDLH", "Basic work clothes when the atmosphere is known to be safe and no skin hazard exists", "A fully encapsulating suit", "Always required on Superfund sites"], a: 1, why: "Do not “upgrade” or “downgrade” casually. Monitoring supports the level." },
  { id: "hz-22", category: "hazwoper", topic: "Heat in PPE", q: "Working in chemical-protective clothing increases:", choices: ["Heat stress risk; rest, hydration, and physiological monitoring may be needed", "Cold stress only", "Hearing acuity", "Oxygen in the suit always"], a: 0, why: "HAZWOPER medical and heat programs overlap. Fully encapsulating suits are ovens." },
  { id: "hz-23", category: "hazwoper", topic: "Compatibility", q: "Glove and suit materials must be:", choices: ["Chosen for chemical compatibility and breakthrough time, not just color", "Always nitrile for every chemical", "Latex for solvents always", "Cotton for acids"], a: 0, why: "A chemical that passes through nitrile in minutes may be fine in butyl or Viton. Check charts." },
  { id: "hz-24", category: "hazwoper", topic: "Post-emergency", q: "After an emergency, cleanup of spilled hazardous substances may fall under:", choices: ["HAZWOPER cleanup provisions if it is a hazardous-waste operation as defined", "No OSHA standard", "Only fire codes", "The forklift standard only"], a: 0, why: "Once the emergency is over, remaining cleanup can be 1910.120(b)–(o) rather than (q)." },
  { id: "hz-25", category: "hazwoper", topic: "DOT ERG", q: "The DOT Emergency Response Guidebook is used to:", choices: ["Find initial isolation distances and general hazards from placards/IDs at a transportation incident", "Replace SDS in the workplace always", "Certify HAZMAT technicians", "Set PELs"], a: 0, why: "ERG is for first responders at a distance. It is not a substitute for a full IAP or SDS at a fixed facility." },

  { id: "bb-01", category: "bloodborne", topic: "Standard", q: "The Bloodborne Pathogens Standard is:", choices: ["1910.1030", "1926.501", "1910.147", "1904.39"], a: 0, why: "It covers occupational exposure to blood and other potentially infectious materials (OPIM)." },
  { id: "bb-02", category: "bloodborne", topic: "OPIM", q: "OPIM includes:", choices: ["Only sweat", "Human body fluids such as semen, vaginal secretions, cerebrospinal fluid, and any body fluid visibly contaminated with blood, among others listed", "Only animal blood in every case", "Drinking water"], a: 1, why: "1910.1030(b): definitions. Sweat, tears, and saliva are not OPIM unless visibly bloody (saliva in dental is OPIM)." },
  { id: "bb-03", category: "bloodborne", topic: "ECP", q: "Employers must have a written:", choices: ["Exposure Control Plan, reviewed at least annually", "Only a first-aid kit list", "Fire drill log", "Forklift route map"], a: 0, why: "1910.1030(c): ECP includes exposure determination, methods of compliance, and procedures for evaluating incidents." },
  { id: "bb-04", category: "bloodborne", topic: "Universal", q: "Universal (standard) precautions means:", choices: ["Treat all blood and OPIM as infectious", "Only treat known HIV-positive patients as infectious", "Gloves are optional", "Wash once a week"], a: 0, why: "You cannot tell who is infectious. Use barriers every time." },
  { id: "bb-05", category: "bloodborne", topic: "Engineering", q: "Examples of engineering controls for BBP include:", choices: ["Sharps containers, self-sheathing needles, and needleless systems", "Memos", "Asking people not to bleed", "Playing music"], a: 0, why: "1910.1030(d)(2): engineering and work-practice controls first. Employers must evaluate safer devices annually." },
  { id: "bb-06", category: "bloodborne", topic: "Sharps container", q: "Contaminated sharps must be discarded in:", choices: ["A coffee cup", "Closable, puncture-resistant, leakproof, labeled or color-coded containers", "The regular trash if recapped", "A paper bag"], a: 1, why: "Do not recap by two-handed technique. Use a one-handed scoop or a mechanical device if recapping is required." },
  { id: "bb-07", category: "bloodborne", topic: "HBV vaccine", q: "Hepatitis B vaccination must be:", choices: ["Offered free after the worker pays for the first two doses", "Made available at no cost after training and within 10 working days of assignment to duties with occupational exposure, unless already immune or the vaccine is contraindicated", "Optional for the employer to mention", "Required to be paid by the worker’s insurance only"], a: 1, why: "1910.1030(f)(2). Declination must be in writing. The worker can still get the vaccine later." },
  { id: "bb-08", category: "bloodborne", topic: "Post-exposure", q: "After an exposure incident, the employer must:", choices: ["Provide a confidential medical evaluation and follow-up at no cost, including testing the source if consent is obtained", "Fire the worker", "Wait 6 months to see", "Only wash the area with solvent"], a: 0, why: "1910.1030(f)(3): immediate first aid, report, evaluation, prophylaxis as recommended by the U.S. Public Health Service." },
  { id: "bb-09", category: "bloodborne", topic: "Labels", q: "Biohazard labels are:", choices: ["Fluorescent orange or orange-red with the biohazard symbol", "Blue and white", "Green", "Optional on sharps boxes"], a: 0, why: "1910.1030(g)(1): red bags or labels. Laundry and regulated waste need identification." },
  { id: "bb-10", category: "bloodborne", topic: "Training BBP", q: "BBP training is required:", choices: ["At assignment and at least annually", "Once per career", "Only for doctors", "Never if you have OSHA 30"], a: 0, why: "1910.1030(g)(2): interactive questions-and-answers with a knowledgeable trainer." },
  { id: "bb-11", category: "bloodborne", topic: "First aid construction", q: "Construction first-aid providers who can reasonably anticipate blood exposure:", choices: ["Can fall under BBP (or a comparable program) even though 1910.1030 is a GI standard — OSHA applies it by policy to construction when there is occupational exposure", "Are never covered", "Only need a hard hat", "Should recap needles in the air"], a: 0, why: "OSHA has stated 1910.1030 can apply to construction where there is occupational exposure. Many GCs put first-aiders in a BBP program." },
  { id: "bb-12", category: "bloodborne", topic: "Handwashing", q: "After removing gloves:", choices: ["Wash hands with soap and water, or use antiseptic cleanser then wash as soon as feasible if no sink was available", "Wipe on pants", "Reuse the same gloves all week", "Rinse with gasoline"], a: 0, why: "1910.1030(d)(2)(v)–(vi): handwashing facilities. Antiseptic towelettes are a temporary measure." },
  { id: "bb-13", category: "bloodborne", topic: "PPE BBP", q: "PPE for BBP is provided:", choices: ["At no cost and must not allow blood/OPIM to pass through to clothes or skin under normal use", "By the worker from home", "Only if the patient looks sick", "As optional fashion"], a: 0, why: "Gloves, gowns, masks, eyewear as the task requires. Hypoallergenic alternatives if needed." },
  { id: "bb-14", category: "bloodborne", topic: "HIV HBV HCV", q: "The three bloodborne viruses of greatest occupational concern are typically:", choices: ["HIV, hepatitis B, and hepatitis C", "Influenza, measles, and mumps only", "Tetanus only", "COVID only"], a: 0, why: "HBV has a vaccine. HCV and HIV do not (for HCV, treatment has improved but prevention still matters). Tetanus is not a bloodborne virus in this sense." },
  { id: "bb-15", category: "bloodborne", topic: "Regulated waste", q: "Regulated waste includes:", choices: ["Liquid or semi-liquid blood/OPIM, contaminated items that would release if compressed, and contaminated sharps", "Office paper", "Empty water bottles", "Clean unused gloves still in the box"], a: 0, why: "Dispose in labeled/color-coded containers. Follow state medical-waste rules too." },

  { id: "wd-01", category: "welding", topic: "Subpart", q: "Construction welding and cutting is mainly:", choices: ["1926 Subpart J", "1926 Subpart M", "1910.147", "1926 Subpart P"], a: 0, why: "1926.350–354. General industry welding is 1910.251–255." },
  { id: "wd-02", category: "welding", topic: "Goggles", q: "Helpers and others exposed to the arc need:", choices: ["No eye protection if they look away sometimes", "Filter lenses or screens so they are not exposed to the arc", "Only hard hats", "Clear glass"], a: 1, why: "UV from the arc causes “welder’s flash” (photokeratitis) to bystanders too. Use screens." },
  { id: "wd-03", category: "welding", topic: "Cylinders upright", q: "Compressed gas cylinders in use should be:", choices: ["Laid down so they cannot fall", "Secured upright with valve protection unless designed otherwise (acetylene has special limits on lying down)", "Stored in the spark stream", "Used as rollers"], a: 1, why: "1926.350: secure, caps on when not in use, acetylene not above 15 psig." },
  { id: "wd-04", category: "welding", topic: "Acetylene pressure", q: "Acetylene working pressure should not exceed:", choices: ["15 psig", "150 psig", "2,000 psig", "The oxygen pressure always"], a: 0, why: "Acetylene is unstable above 15 psig in free state. Use the correct regulator." },
  { id: "wd-05", category: "welding", topic: "Oil oxygen", q: "Oil or grease on oxygen fittings is:", choices: ["A good lubricant", "Dangerous — oxygen can cause oil to ignite or explode", "Required by OSHA", "Only a housekeeping issue"], a: 1, why: "Keep oxygen equipment clean. Never use oil on regulators or threads." },
  { id: "wd-06", category: "welding", topic: "Flashback", q: "Flashback arrestors and reverse-flow check valves:", choices: ["Help prevent fire from traveling back into hoses and cylinders", "Increase cutting speed only", "Replace cylinder caps", "Are decorative"], a: 0, why: "Manufacturer and OSHA/CGA practices. Inspect hoses for cuts and burns." },
  { id: "wd-07", category: "welding", topic: "Hot work permit", q: "A hot-work permit system is used to:", choices: ["Control welding/cutting in areas with combustibles — inspect, protect, and assign fire watch", "Speed up production by skipping fire watch", "Replace fire extinguishers", "Allow welding in explosive atmospheres"], a: 0, why: "1910.252 / 1926.352: move combustibles, use guards, fire watch." },
  { id: "wd-08", category: "welding", topic: "Confined weld", q: "Welding in a confined space requires:", choices: ["Local exhaust or supplied air as needed, atmospheric testing, and never using oxygen for ventilation", "Pure oxygen to keep the arc stable", "No attendant", "Closed cylinders inside the space as storage"], a: 0, why: "1926.353 / 1910.252(c): ventilation. Remove cylinders from confined spaces when possible during breaks as specified." },
  { id: "wd-09", category: "welding", topic: "Coatings", q: "Welding on painted or plated metal can release:", choices: ["Only steam", "Lead, cadmium, zinc (metal fume fever), isocyanates, or chromates depending on the coating", "Pure oxygen", "Helium only"], a: 1, why: "Strip coatings or use LEV/respirators. SDS the coating if you can." },
  { id: "wd-10", category: "welding", topic: "Zinc fume", q: "Metal fume fever is commonly associated with:", choices: ["Welding or cutting galvanized steel (zinc oxide fume)", "Drinking water", "Wood dust only", "Silica sand only"], a: 0, why: "Flu-like symptoms hours after exposure. Ventilate and avoid eating in the plume." },
  { id: "wd-11", category: "welding", topic: "Grounding", q: "The welding return (work) clamp should be:", choices: ["Attached to the workpiece or a proper work lead — not through building steel, pipes, or chains as a casual path if it can arc and fire", "Clamped to a fire sprinkler pipe as best practice", "Skipped on DC welders", "Held by a helper with bare hands"], a: 0, why: "Stray welding current starts fires and damages circuits. Put the clamp close to the weld." },
  { id: "wd-12", category: "welding", topic: "Electrode holders", q: "Electrode holders must be:", choices: ["Fully insulated and not dipped in water to cool", "Left on the ground with a live electrode", "Wrapped with duct tape as the listed insulation", "Held in the mouth"], a: 0, why: "1926.351: insulation. Do not dip hot holders in water." },
  { id: "wd-13", category: "welding", topic: "Cables", q: "Welding cables with damaged insulation:", choices: ["Must be repaired or replaced; do not tape as a permanent fix on a live conductor casually", "Are fine if the copper shows", "Work better", "Should be cooled in oil"], a: 0, why: "1926.351(b): cables in need of repair shall not be used." },
  { id: "wd-14", category: "welding", topic: "Screens", q: "Welding screens protect others from:", choices: ["Arc radiation and sparks", "Noise only", "Silica only", "Cave-ins"], a: 0, why: "Place screens so they do not restrict ventilation. Non-reflective finishes help." },
  { id: "wd-15", category: "welding", topic: "Fire extinguisher weld", q: "Suitable fire extinguishing equipment must be:", choices: ["Ready in the work area for hot work", "In another building", "Optional if you have a bottle of water", "Only Class D"], a: 0, why: "1926.352(d): extinguishers or other firefighting equipment shall be immediately available." },
  { id: "wd-16", category: "welding", topic: "Drums", q: "Welding on drums or tanks that held flammables:", choices: ["Is safe if they “look empty”", "Requires cleaning, inerting, or other procedures so vapors cannot explode", "Is the best way to open them", "Needs no testing"], a: 1, why: "Empty drums explode. Follow 1910.252(a)(3) / 1926.352(i) and industry practices (purging, inerting)." },
  { id: "wd-17", category: "welding", topic: "PPE weld", q: "Welders typically need:", choices: ["Filter lens, flame-resistant clothing, leather or equivalent for sparks, and hearing/respiratory protection as the task requires", "Short sleeves and synthetic hoodies", "Only a paper mask", "Cotton soaked in solvent"], a: 0, why: "Synthetics melt. Cover skin from UV. Use the right shade." },
  { id: "wd-18", category: "welding", topic: "Ventilation rate", q: "When welding in a space with less than 10,000 cf per welder without local exhaust, OSHA construction rules may require:", choices: ["Mechanical ventilation meeting specified cfm or respiratory protection as applicable", "No extra air", "Oxygen enrichment", "Closing all doors"], a: 0, why: "1926.353: 2,000 cfm per welder in some cases, or local exhaust, or respirators. Know the specific paragraph for the process." },
  { id: "wd-19", category: "welding", topic: "Cylinder transport", q: "When moving cylinders they should be:", choices: ["Capped, secured, and not lifted by the cap unless it is designed as a lifting device (most are not)", "Rolled horizontally while connected to the regulator", "Carried by the valve", "Chucked in a truck bed loose"], a: 0, why: "1926.350(a): valve protection caps in place. Use a cart." },
  { id: "wd-20", category: "welding", topic: "Arc vs gas", q: "A key extra hazard of SMAW/GMAW vs oxy-fuel is:", choices: ["Electric shock and UV/IR radiation from the arc", "No fumes", "No fire risk", "No need for eye protection"], a: 0, why: "Both have fire and fume hazards. Arc adds electricity and intense radiation." },

  { id: "st-01", category: "steel", topic: "Subpart R", q: "Steel erection is covered by:", choices: ["1926 Subpart R", "1910.147", "1926 Subpart P", "1910.1030"], a: 0, why: "1926.750–761: site layout, hoisting, fall protection, and training." },
  { id: "st-02", category: "steel", topic: "15 feet", q: "Except for connectors and certain decking work, steel erection fall protection is generally required at:", choices: ["6 feet", "15 feet", "30 feet", "Only at 25 feet"], a: 1, why: "1926.760(a): 15 feet. Connectors have additional rules between 15 and 30 feet." },
  { id: "st-03", category: "steel", topic: "Connectors", q: "A connector in steel erection:", choices: ["May work without fall protection between 15 and 30 feet if they are trained, have completed decking/access, and have PFAS available for immediate use as specified", "Never needs fall protection", "Must use guardrails at 4 feet", "Is exempt at all heights"], a: 0, why: "1926.760(b): connector provisions are specific. At 30 feet they must be protected." },
  { id: "st-04", category: "steel", topic: "Controlled decking", q: "A Controlled Decking Zone (CDZ) allows:", choices: ["Leading-edge decking work between 15 and 30 feet with specific procedures instead of conventional PFAS for those leading-edge workers", "No protection at 40 feet", "Anyone to walk the edge", "Skipping metal deck attachments"], a: 0, why: "1926.760(c): CDZ is tightly limited — trained employees, no other work, 90-foot width max, etc." },
  { id: "st-05", category: "steel", topic: "Tripping shear studs", q: "Shear connectors that are a trip hazard on walking surfaces:", choices: ["Shall not be attached until after the decking is installed, as specified", "Must be installed first always", "Replace fall protection", "Are painted to be visible only"], a: 0, why: "1926.754(c)(1): control trip hazards from shear connectors, reinforcing bars, etc." },
  { id: "st-06", category: "steel", topic: "Plumbing up", q: "Plumbing-up equipment must be:", choices: ["Installed under the supervision of a competent person and left in place until the steel is secured", "Removed immediately after the first bolt", "Optional guy wires of any size", "Tied to a pickup bumper"], a: 0, why: "1926.752 and .754: stability. Do not remove braces until the structure can stand." },
  { id: "st-07", category: "steel", topic: "Two bolts", q: "Before releasing a member from the hoist line, it generally must have:", choices: ["At least two bolts per connection, wrench-tight, drawn up, or the equivalent as specified", "One tack weld", "A single drift pin only", "Nothing — set it on the flange"], a: 0, why: "1926.756(a): two bolts per connection (or equivalent) before unhooking, with exceptions in the standard for some joints." },
  { id: "st-08", category: "steel", topic: "Column anchor", q: "Columns must be:", choices: ["Anchored by a minimum of four anchor rods/bolts, among other requirements", "Set on wood shims only", "Free-standing with no anchors at any height", "Welded to rebar in the mud"], a: 0, why: "1926.755: four anchor rods, and a competent person evaluates adequacy. Repair of damaged rods is specified." },
  { id: "st-09", category: "steel", topic: "Site layout", q: "Before steel erection begins, the controlling contractor must provide:", choices: ["Written notification that concrete in piers/walls/footings has reached specified strength (75% or as specified) and site layout/access info", "Only a handshake", "No information", "A blank site map"], a: 0, why: "1926.752: controlling contractor duties. Erectors need adequate access roads and laydown." },
  { id: "st-10", category: "steel", topic: "Hoisting", q: "During steel hoisting, workers should not:", choices: ["Be under the load except for connectors who are necessary to the process and following the standard", "Use tag lines when needed", "Have a qualified rigger", "Use a lift plan for complex picks"], a: 0, why: "1926.753: routes, pre-planning, and the prohibition on being under loads with a connector exception." },
  { id: "st-11", category: "steel", topic: "Decking holes", q: "Holes in metal deck must be:", choices: ["Covered, guarded, or marked and protected so people do not step through", "Left open for wiring later", "Covered with insulation blanket only", "Ignored under 12 inches"], a: 0, why: "1926.754(e) and fall protection rules. Skylight openings too." },
  { id: "st-12", category: "steel", topic: "Training steel", q: "Steel erectors must train workers on:", choices: ["Fall hazards, multiple-lift rigging if used, and CDZ procedures if used, among other topics", "Only payroll", "Only first aid", "Nothing if they have OSHA 10"], a: 0, why: "1926.761: qualified person provides training. OSHA 10 is awareness, not Subpart R certification." },
  { id: "st-13", category: "steel", topic: "Multiple lift", q: "Multiple-lift rigging (Christmas-treeing) is allowed only when:", choices: ["A multiple-lift rigging assembly is used, members are similar, five or fewer, and other 1926.753(e) conditions are met", "You need to go faster with chokers of any type", "Always banned", "Only with a forklift"], a: 0, why: "Strict conditions. Cranes and rigging must be designed for it." },
  { id: "st-14", category: "steel", topic: "Purlins", q: "Walking on steel joists or purlins:", choices: ["Requires they be adequately bridged/secured; do not walk on unsecured joists", "Is always safe", "Needs no fall protection at 20 feet", "Is preferred to using platforms"], a: 0, why: "1926.757 and .754: bridging, erection bridging, and fall protection. Unsecured joists roll." },
  { id: "st-15", category: "steel", topic: "Falling objects steel", q: "Loose items aloft should be:", choices: ["Secured against falling; containers for bolts and drift pins", "Kicked off the iron to the ground crew", "Left on the flange", "Thrown in a bag over the side"], a: 0, why: "1926.759: falling-object protection. Toeboards, nets, or canopies as required; secure tools." },

  { id: "cn-01", category: "concrete", topic: "Subpart Q", q: "Construction concrete and masonry are mainly:", choices: ["1926 Subpart Q", "1926 Subpart L", "1910.120", "1926 Subpart CC"], a: 0, why: "1926.700–706: cast-in-place, precast, lift-slab, masonry, and limited access zones." },
  { id: "cn-02", category: "concrete", topic: "Impalement", q: "Protruding reinforcing steel must be:", choices: ["Guarded to prevent impalement (caps meeting the standard or troughs, not mushroom caps that fail tests)", "Left sharp so people notice", "Painted orange only", "Bent by apprentices as a rite"], a: 0, why: "1926.701(b): protect from impalement. Use devices that actually work — OSHA has cited fake “mushroom” caps." },
  { id: "cn-03", category: "concrete", topic: "Limited access masonry", q: "A limited access zone for masonry walls:", choices: ["Is established on the unscaffolded side, equal to the height plus 4 feet, running the length of the wall, restricted to masons, until the wall is supported", "Is 3 feet always", "Is optional for walls over 8 feet", "Replaces bracing"], a: 0, why: "1926.706(a): LAZ. Walls over 8 feet need bracing until permanent support unless adequately supported otherwise." },
  { id: "cn-04", category: "concrete", topic: "Masonry brace", q: "A masonry wall over 8 feet high must be:", choices: ["Braced until permanent supporting elements are in place, unless it can stand without bracing", "Left free-standing in the wind", "Held up by workers", "Only toeboarded"], a: 0, why: "1926.706(b): prevent collapse. Wind and green masonry are a deadly mix." },
  { id: "cn-05", category: "concrete", topic: "Shoring", q: "Formwork and shoring must be:", choices: ["Designed, erected, supported, braced, and maintained so they will support all loads", "Built from any scrap", "Removed while concrete is still plastic always", "Climbed as a ladder even if not designed for it"], a: 0, why: "1926.703: drawings, inspections, and reshoring. Failures cause multiple fatalities." },
  { id: "cn-06", category: "concrete", topic: "Drawings", q: "Formwork drawings and plans must be:", choices: ["Available at the jobsite", "Left at the engineer’s office only", "Verbal", "Optional under 20 feet"], a: 0, why: "1926.703(a)(2): plans on site. A competent person inspects before, during, and after concrete placement as specified." },
  { id: "cn-07", category: "concrete", topic: "Precast", q: "Precast members must not be used for storage or have loads applied until:", choices: ["They can support the load without excessive stress — follow the erector/engineer", "The truck leaves", "Paint dries", "OSHA visits"], a: 0, why: "1926.704: lifting inserts, bracing, and erection procedures. Never walk a wall that is not braced." },
  { id: "cn-08", category: "concrete", topic: "Tilt-up", q: "During tilt-up erection, workers should not be:", choices: ["Under the panel", "Using tag lines from a safe location", "Following the erection plan", "Wearing PPE"], a: 0, why: "1926.705: lift-slab has extra rules. Tilt-up panels crush people in the fall zone." },
  { id: "cn-09", category: "concrete", topic: "Concrete buckets", q: "Riding a concrete bucket is:", choices: ["Prohibited", "Allowed if you hold the cable", "Required for placement", "Fine under 10 feet"], a: 0, why: "1926.701(d): no riding the bucket. Keep workers away from the bucket’s travel." },
  { id: "cn-10", category: "concrete", topic: "Pump hose", q: "Concrete pump lines can:", choices: ["Whip and strike workers; use proper systems, supports, and PPE; never look into a plugged hose", "Be held by hand at the coupling during a blowout", "Be used as a swing", "Skip blocks and cribbing"], a: 0, why: "Secure hose, use proper reducers, and treat blockages with procedures — not your face." },
  { id: "cn-11", category: "concrete", topic: "Silica concrete", q: "Cutting, grinding, or drilling concrete is a:", choices: ["Silica-generating task — use Table 1 wet methods or equivalent", "Dust-free task", "Only a noise task", "Lead task always"], a: 0, why: "1926.1153 Table 1 lists saws, grinders, and drills. Water or shrouded vacuums." },
  { id: "cn-12", category: "concrete", topic: "Cement burns", q: "Wet concrete and cement can cause:", choices: ["Caustic chemical burns and dermatitis; use PPE and wash off", "No skin effect", "Only dust in the eyes never skin", "Frostbite"], a: 0, why: "Alkaline burns can be severe. Boots, gloves, and eyewash. Do not work in soaked clothes." },
  { id: "cn-13", category: "concrete", topic: "Masonry scaffold", q: "Masonry overhand work on scaffolds still needs:", choices: ["Fall protection per Subpart L and falling-object protection for people below", "No rails because masons need to reach", "Only a LAZ on the scaffold", "Body belts"], a: 0, why: "Do not remove guardrails to lay brick without another system. Outrigger platforms and properly designed systems exist." },
  { id: "cn-14", category: "concrete", topic: "Post-tension", q: "During post-tensioning, workers should not be:", choices: ["Behind the jack (the tendon can shoot) — stay out of the line of fire", "Following the stressing procedure", "Using calibrated equipment", "Wearing eye protection"], a: 0, why: "1926.701(c): no employees under the tendon during stressing except those required. The wedge side is a missile hazard." },
  { id: "cn-15", category: "concrete", topic: "Lockout concrete", q: "Before reaching into a concrete mixer or pump hopper:", choices: ["Lockout/tagout the equipment", "Just shout “hold it”", "Reach in while it is jogging", "Use a stick while it runs"], a: 0, why: "Caught-in hazard. Isolate energy. Mixers kill." },

  { id: "rp-01", category: "respiratory", topic: "Standard", q: "The Respiratory Protection Standard is:", choices: ["1910.134 (applied to construction via 1926.103)", "1926.501", "1910.178", "1904.7"], a: 0, why: "Written program, medical, fit testing, training, and cartridge change schedules." },
  { id: "rp-02", category: "respiratory", topic: "Written program", q: "A written respiratory program is required when:", choices: ["Respirators are necessary to protect health or required by the employer", "Only if you have 100 employees", "Never for N95s", "Only in mining"], a: 0, why: "1910.134(c): program administrator, procedures, and site-specific details. Voluntary use has a smaller set of duties (Appendix D)." },
  { id: "rp-03", category: "respiratory", topic: "Voluntary N95", q: "If an employer allows voluntary use of a filtering facepiece (dust mask) where no respirator is required:", choices: ["Provide Appendix D information; a full program is not required for the dust mask itself (medical still applies to elastomeric voluntary use)", "Do nothing", "Fit test monthly", "Issue SCBA"], a: 0, why: "1910.134(c)(2): distinguish filtering facepiece vs elastomeric voluntary use. Elastomeric voluntary use still needs medical evaluation and cleaning." },
  { id: "rp-04", category: "respiratory", topic: "Medical PLHCP", q: "Medical evaluation is done by:", choices: ["A physician or other licensed health-care professional (PLHCP), using the questionnaire or an exam", "The foreman", "A coworker who “looks healthy”", "OSHA online"], a: 0, why: "1910.134(e): follow-up exam if the questionnaire indicates it. Employer pays and it is confidential." },
  { id: "rp-05", category: "respiratory", topic: "Fit test types", q: "Qualitative fit tests include:", choices: ["Saccharin, Bitrex, isoamyl acetate (banana oil), and irritant smoke (with limits)", "PortaCount only", "A mirror check only", "Holding your breath"], a: 0, why: "QLFT is pass/fail by taste/smell/irritation. QNFT measures leakage numerically. QLFT generally only for APF 10." },
  { id: "rp-06", category: "respiratory", topic: "User seal check", q: "A user seal check is performed:", choices: ["Every time the respirator is put on", "Once a year", "Only in the office", "Never with N95s"], a: 0, why: "1910.134(f)(1)(ii) and Appendix B-1: positive and/or negative pressure checks. It is not a substitute for annual fit testing." },
  { id: "rp-07", category: "respiratory", topic: "Change schedule", q: "For gas/vapor cartridges, the employer must:", choices: ["Use an end-of-service-life schedule based on data, or an ESLI if reliable, not just “when I smell it” as the primary plan for many chemicals", "Change them every 5 years", "Never change them", "Rely only on odor always"], a: 0, why: "1910.134(d)(3)(iii): warning properties are not sufficient for many chemicals (including CO, which has none)." },
  { id: "rp-08", category: "respiratory", topic: "N95 meaning", q: "N95 means the filter:", choices: ["Is not oil-resistant and filters at least 95% of test aerosol", "Stops 95% of gases", "Is good for IDLH", "Supplies oxygen"], a: 0, why: "N = not oil, R = resistant, P = oil-proof. 95/99/100 are efficiencies. Filters do not add oxygen or stop many vapors." },
  { id: "rp-09", category: "respiratory", topic: "Oxygen deficient", q: "Air-purifying respirators shall not be used in:", choices: ["Oxygen-deficient atmospheres (generally under 19.5%) or IDLH unless the respirator is designed for that (SCBA/SAR)", "Nuisance dust below the PEL with voluntary use", "Pollen outdoors", "Paint fumes if the cartridge is rated and oxygen is normal, as part of a program"], a: 0, why: "APRs need oxygen. They also need the right cartridge and a concentration below IDLH and below maximum use concentration." },
  { id: "rp-10", category: "respiratory", topic: "MUC", q: "Maximum use concentration is roughly:", choices: ["APF times the PEL (with IDLH as a cap)", "100 times any PEL always", "The odor threshold", "Zero"], a: 0, why: "MUC = APF × occupational exposure limit, not to exceed IDLH. Full-face APF 50 × PEL, etc." },
  { id: "rp-11", category: "respiratory", topic: "Storage", q: "Respirators must be stored:", choices: ["To protect from damage, dust, sunlight, heat, and deformation — not dangling on a nail in the rain", "In the chemical tote", "Inside a grinding booth unprotected", "Under the truck seat mixed with oil"], a: 0, why: "1910.134(h): clean, inspect, and store. Facepieces that are crushed will leak." },
  { id: "rp-12", category: "respiratory", topic: "SCBA", q: "SCBA for IDLH entry requires:", choices: ["Pressure-demand or other positive pressure, 30-minute rated minimum generally, and a standby person with rescue equipment", "A dust mask and a buddy far away", "Demand-mode negative pressure", "No training"], a: 0, why: "1910.134(g)(3) and (d)(2). Interior firefighting has NFPA overlap." },
  { id: "rp-13", category: "respiratory", topic: "Beards", q: "Tight-fitting respirators and beards:", choices: ["Are incompatible if hair breaks the seal", "Are fine with extra straps", "Are required together", "Only matter for SCBA"], a: 0, why: "1910.134(g)(1)(i): no hair in the sealing surface. Offer a PAPR with a loose hood if the program allows and APF is enough." },
  { id: "rp-14", category: "respiratory", topic: "Glasses", q: "Spectacle kits for full-face respirators:", choices: ["Allow prescription lenses without breaking the seal — do not wear street glasses under a full-face in a way that leaks", "Are banned", "Replace the need to fit test", "Are only for welding"], a: 0, why: "Temple bars break the seal. Use inserts designed for the facepiece." },
  { id: "rp-15", category: "respiratory", topic: "Training resp", q: "Respirator training is required:", choices: ["Initially and at least annually, and when necessary due to changes or inadequate knowledge", "Once", "Only for the program administrator", "Never if Appendix D was handed out for required use"], a: 0, why: "1910.134(k): demonstrate how to inspect, don, do a seal check, and know limitations." },

  { id: "mg-01", category: "machineguard", topic: "Standard", q: "Machine guarding in general industry is primarily:", choices: ["1910.212 (general) plus machine-specific rules (saws, mills, etc.)", "1926.501", "1910.1200", "1904 only"], a: 0, why: "Point of operation, ingoing nip points, rotating parts, and flying chips must be guarded." },
  { id: "mg-02", category: "machineguard", topic: "Point of operation", q: "The point of operation is:", choices: ["Where the work is actually performed on the material (cutting, shaping, boring)", "The start button", "The break room", "The motor only"], a: 0, why: "1910.212(a)(3): guard the point of operation if it exposes operators to injury." },
  { id: "mg-03", category: "machineguard", topic: "Fan blades", q: "When the periphery of fan blades is less than 7 feet above the floor or working level, blades must be:", choices: ["Guarded with openings no larger than 1/2 inch", "Unguarded for airflow", "Painted yellow only", "Removed"], a: 0, why: "1910.212(a)(5): 1/2-inch maximum openings on fan guards." },
  { id: "mg-04", category: "machineguard", topic: "Anchoring", q: "Machines designed for a fixed location must be:", choices: ["Anchored to prevent walking or moving", "On wheels without locks always", "Held by the operator", "Placed on cardboard"], a: 0, why: "1910.212(b): anchoring. Drill presses and grinders “walk” and cause injury." },
  { id: "mg-05", category: "machineguard", topic: "Table saw", q: "A table saw should have:", choices: ["A blade guard, riving knife/spreader, and anti-kickback devices as designed; never remove them for through cuts", "No guard so you can see", "A dado stack without any protection ever", "The fence on the left only as a rule"], a: 0, why: "1910.213: woodworking. Kickback kills. Use push sticks and keep guards on." },
  { id: "mg-06", category: "machineguard", topic: "Power press", q: "Mechanical power presses have:", choices: ["Detailed 1910.217 rules including presence-sensing, pullbacks, two-hand controls, and lockout for die setting", "No standard", "Only a sign", "Guards that may be tied back permanently"], a: 0, why: "Amputations are common. Presence-sensing device initiation has extra requirements. Never bypass light curtains." },
  { id: "mg-07", category: "machineguard", topic: "LOTO vs guards", q: "Machine guards protect during:", choices: ["Normal production; LOTO protects during servicing when guards are removed or bypassed", "Servicing only", "Neither", "Only electrical work"], a: 0, why: "If you reach around a guard or take it off, you need 1910.147 (or the minor servicing exception if it truly applies)." },
  { id: "mg-08", category: "machineguard", topic: "Interlocks", q: "Guard interlocks should:", choices: ["Stop the hazardous motion when the guard is opened; they must not be easy to defeat", "Be taped over to run faster", "Be optional", "Only light an LED"], a: 0, why: "Defeating interlocks is a leading amputation cause. ANSI B11 and OSHA both care." },
  { id: "mg-09", category: "machineguard", topic: "Nip points", q: "In-running nip points occur at:", choices: ["Rotating cylinders, belts and pulleys, and meshing gears", "Flat tables with no motion", "Ladders", "Hard hats"], a: 0, why: "Hair, clothing, and fingers get drawn in. Guard or locate at a safe distance." },
  { id: "mg-10", category: "machineguard", topic: "PTO", q: "Power take-off shafts on equipment must be:", choices: ["Guarded", "Used as a step", "Left uncovered on farms only so OSHA never applies (farms can still have rules/exceptions, but industry PTOs need guards)", "Painted only"], a: 0, why: "1910.219 machinery and construction equipment: rotating shafts grab clothes in a second." },
  { id: "mg-11", category: "machineguard", topic: "Hand tools", q: "Using a hand tool to feed a machine:", choices: ["Can keep hands out of the point of operation when designed that way", "Means guards can always come off", "Is banned", "Replaces lockout for repairs inside the machine"], a: 0, why: "Push sticks, pliers, and fixtures are work methods. They do not replace required guards." },
  { id: "mg-12", category: "machineguard", topic: "Construction tools", q: "Construction power tools must have:", choices: ["Guards kept in place (1926.300)", "Guards removed for concrete work always", "No cords", "Metal housings on all double-insulated tools"], a: 0, why: "Circular saws, abrasive wheels, and grinders: guards on. Reciprocating saws still need control of the blade." },
  { id: "mg-13", category: "machineguard", topic: "E-stop", q: "Emergency stops should be:", choices: ["Accessible, clearly marked, and not used as the normal stop if the design requires a separate disconnect for LOTO", "Hidden behind the machine", "The only lockout device", "Tied in the on position"], a: 0, why: "E-stops are for emergencies. Isolation for servicing still needs a lockable disconnect." },
  { id: "mg-14", category: "machineguard", topic: "Chips", q: "Machines that create flying chips need:", choices: ["Guards, shields, or PPE (and usually both)", "Only hearing protection", "No eye protection if you squint", "A fan to blow chips at others"], a: 0, why: "1910.212(a)(1): flying chips and sparks. Lathes need chip guards." },
  { id: "mg-15", category: "machineguard", topic: "Training machines", q: "Operators must be trained on:", choices: ["Hazards, guards, and not to remove or bypass protection", "Only production quotas", "How to defeat light curtains", "Nothing if the machine is old"], a: 0, why: "1910.212 plus specific standards. Supervisors must enforce guards-on culture." },

  { id: "ae-01", category: "aerial", topic: "MEWP", q: "Mobile elevating work platforms (aerial lifts, scissor lifts, boom lifts) in construction are addressed in:", choices: ["1926.453 and manufacturer instructions; ANSI/SAIA A92 is the industry consensus", "1926.652 only", "1910.1030", "Subpart P only"], a: 0, why: "1926.453 is based on older ANSI A92.2. Follow the manual: fall protection, slope, and wind limits." },
  { id: "ae-02", category: "aerial", topic: "Harness boom", q: "In a boom-supported aerial lift, occupants generally must:", choices: ["Wear a personal fall arrest or travel restraint system attached to the boom or basket as the manufacturer specifies", "Stand on the midrail", "Climb the boom", "Use a body belt for arrest"], a: 0, why: "1926.453(b)(2)(v): body belt with lanyard attached to the boom or basket — modern practice is a full-body harness. Do not tie off to an adjacent structure." },
  { id: "ae-03", category: "aerial", topic: "Scissor PFAS", q: "On scissor lifts, fall protection is primarily:", choices: ["The guardrail system; PFAS is used if the manufacturer requires it or if guardrails are not equivalent", "Always a 6-foot lanyard to the floor below", "Never needed", "A warning line on the ground only"], a: 0, why: "Do not climb rails. If you open a gate or stand on rails, you have created a fall hazard — use restraint/arrest as required." },
  { id: "ae-04", category: "aerial", topic: "Tie-off structure", q: "Tying an aerial lift lanyard to an adjacent building or pole:", choices: ["Can pull you out of the basket if the lift moves — generally prohibited", "Is the preferred anchorage", "Increases capacity", "Replaces outriggers"], a: 0, why: "Anchor to the designated point in the platform. Catapulting out of the basket is a known fatality pattern." },
  { id: "ae-05", category: "aerial", topic: "Weight capacity", q: "Platform capacity includes:", choices: ["Workers, tools, and materials — do not exceed rated load", "Only people, tools are free", "Wind load only", "Unlimited if you move slowly"], a: 0, why: "Read the capacity chart at different reaches (boom lifts). Ice and water add weight." },
  { id: "ae-06", category: "aerial", topic: "Ground conditions", q: "Operating on a slope or soft ground:", choices: ["Can cause tip-over; use outriggers/extend axles as required and stay within slope limits", "Is fine at full height", "Only matters for scissor lifts", "Is solved by driving faster"], a: 0, why: "Level indicators exist for a reason. Cribbing must be adequate. Watch underground vaults." },
  { id: "ae-07", category: "aerial", topic: "Power lines aerial", q: "Aerial lifts near overhead lines need:", choices: ["The same electrical approach distances as other equipment — 10 feet or more, or de-energize", "No clearance if the basket is fiberglass", "3 feet always", "Contact to test if the line is live"], a: 0, why: "1926.453(b)(2)(ix) and 1926.1408 / .416. Insulated booms are for qualified line-clearance work, not a free pass for construction laborers." },
  { id: "ae-08", category: "aerial", topic: "Drop-offs", q: "Scissor lifts near loading docks or trenches:", choices: ["Can drive off the edge; use barricades and spotters", "Are too heavy to fall", "Should be driven with the platform fully raised for visibility", "Need no inspection of the floor"], a: 0, why: "Drive lowered. Inspect slabs for holes. Docks need edge protection." },
  { id: "ae-09", category: "aerial", topic: "Wind", q: "Manufacturer wind ratings:", choices: ["Must be followed; lower the platform or stop work in high wind", "Are optional", "Only apply to cranes", "Increase as you go higher"], a: 0, why: "Sail area of signs, siding, and the platform catch wind. Tip-overs happen in gusts." },
  { id: "ae-10", category: "aerial", topic: "Training aerial", q: "Operators must be:", choices: ["Trained on the model they use, including indoor vs outdoor ratings and emergency lowering", "Self-taught on the first day unsupervised", "Only given the keys", "Certified by OSHA personally"], a: 0, why: "1926.453(b)(2)(ii) and ANSI A92: training and familiarization. Rescue plan if the operator is incapacitated." },
  { id: "ae-11", category: "aerial", topic: "Both feet", q: "Work from the platform with:", choices: ["Both feet on the floor; do not climb guardrails or use ladders in the basket", "One foot on the midrail to gain height", "A 55-gallon drum as a step", "Standing on the toeboard"], a: 0, why: "1926.453(b)(2)(iv): always stand firmly on the floor of the basket. Do not sit or climb the edge." },
  { id: "ae-12", category: "aerial", topic: "Brakes outriggers", q: "Before raising the platform:", choices: ["Set brakes and outriggers/stabilizers as required; on some scissors, retractable deck fully in", "Leave the truck in gear rolling", "Raise first then level", "Disconnect the emergency stop"], a: 0, why: "Pre-use inspection includes functions, controls, leaks, and decals. Do not operate with an active fault." },
  { id: "ae-13", category: "aerial", topic: "Travel elevated", q: "Traveling with a boom lift elevated:", choices: ["Only if the manufacturer allows stowed/limited-speed travel; many require boom stowed", "Always at full height down the highway", "Never with the boom over the cab as a rule for all models", "Is faster than stowing so it is required"], a: 0, why: "Follow the manual. Construction sites have struck-by and tip-over events when people “drive aerial.”" },
  { id: "ae-14", category: "aerial", topic: "Electrocution fiberglass", q: "A fiberglass boom:", choices: ["May be insulated for a specified kV if tested and clean — dirt and moisture reduce insulation; it does not protect occupants who contact a second point", "Makes all electrical work safe for anyone", "Means you can touch primary distribution lines", "Needs no inspection"], a: 0, why: "Only qualified line-clearance crews use insulated aerial devices as designed. Construction workers stay away from lines." },
  { id: "ae-15", category: "aerial", topic: "Rescue aerial", q: "If a worker is stuck aloft or after a fall in the harness:", choices: ["Have a rescue plan (ground controls, second machine, or trained rescue) — do not leave them suspended", "Wait for them to climb down the boom", "Call only the rental company next week", "Shake the lift"], a: 0, why: "Ground controls and emergency descent: train a ground person. Suspension trauma is time-critical." }
];
